#include <iostream>

// Demonstrates structured flow: sequence, stacked blocks, and nested blocks
int main() {
    int count = 0;
    int sum = 0;

    // Block 1 (Stacked): Input loop simulating Böhm-Jacopini while
    int val;
    while (std::cin >> val) {
        // Block 2 (Nested within while): Selection using if
        if (val < 0) {
            break; // Structured exit on negative sentinel
        }
        sum += val;
        count++;
    }

    // Block 3 (Stacked after while): Structured output decision
    if (count > 0) {
        std::cout << "Count: " << count << "\n";
        std::cout << "Sum: " << sum << "\n";
    } else {
        std::cout << "No valid data processed.\n";
    }

    return 0;
}

#include <iostream>

// Demonstrates secure input extraction and range checking in C++17
int main() {
    int grade = 0;

    // Validate extraction: std::cin >> grade ensures type safety
    if (std::cin >> grade) {
        // Range checking: ensure grade is within [0, 100]
        if (grade >= 0 && grade <= 100) {
            std::cout << "Valid grade: " << grade << "\n";
            if (grade >= 50) {
                std::cout << "Status: Passed\n";
            } else {
                std::cout << "Status: Failed\n";
            }
        } else {
            std::cout << "Error: Grade " << grade << " out of range [0, 100].\n";
        }
    } else {
        std::cout << "Error: Non-integer input encountered.\n";
    }

    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

// Demonstrates for loop, comma operator, pow, formatting, and switch
int main() {
    std::cout << std::left << std::setw(8) << "Year"
              << std::right << std::setw(15) << "Amount" << "\n";

    double principal = 1000.0;
    double rate = 0.05;

    // Using for loop with counter-controlled iteration
    for (int year = 1; year <= 3; year++) {
        double amount = principal * std::pow(1.0 + rate, year);

        std::cout << std::left << std::setw(8) << year
                  << std::right << std::fixed << std::setprecision(2)
                  << std::setw(15) << amount;

        // Inspecting tier using switch
        switch (year) {
            case 1:
                std::cout << "  [Initial Year]\n";
                break;
            case 2:
                std::cout << "  [Mid Term]\n";
                break;
            default:
                std::cout << "  [Mature Term]\n";
                break;
        }
    }

    return 0;
}
